def solve_nqueens():
    n = 5
    fixed = {1: 2}  # q[1] = 2

    def is_valid(placement, row, col):
        for r, c in placement.items():
            if c == col:
                return False
            if abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row, placement):
        if row == n:
            return placement
        if row in fixed:
            col = fixed[row]
            if is_valid(placement, row, col):
                placement[row] = col
                result = backtrack(row + 1, placement)
                if result:
                    return result
                del placement[row]
            return None
        for col in range(n):
            if is_valid(placement, row, col):
                placement[row] = col
                result = backtrack(row + 1, placement)
                if result:
                    return result
                del placement[row]
        return None

    solution = backtrack(0, {})
    return solution

sol = solve_nqueens()
if sol:
    result = [sol[i] for i in range(5)]
    print("Solution found:", result)
    # Verify
    print("\nBoard:")
    for r in range(5):
        row_str = ""
        for c in range(5):
            row_str += "Q " if result[r] == c else ". "
        print(row_str)
    # Check no attacks
    ok = True
    for i in range(5):
        for j in range(i+1, 5):
            if result[i] == result[j]:
                ok = False
            if abs(i-j) == abs(result[i]-result[j]):
                ok = False
    print("\nValid:", ok)
else:
    print("UNSATISFIABLE")
